use std::rc::Rc;use std::cell::RefCell;impl Solution{pub fn path_sum(root:Option<Rc<RefCell<TreeNode>>>,t:i32)->Vec<Vec<i32>>{fn f(n:&Option<Rc<RefCell<TreeNode>>>,t:i32,v:&mut Vec<i32>,o:&mut Vec<Vec<i32>>){if let Some(x)=n{let b=x.borrow();v.push(b.val);let r=t-b.val;if b.left.is_none()&&b.right.is_none()&&r==0{o.push(v.clone())}else{f(&b.left,r,v,o);f(&b.right,r,v,o);}v.pop();}}let mut o=vec![];f(&root,t,&mut vec![],&mut o);o}}
